head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > setCellDisplayFormat]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에 데이터가 표시되는 형식을 마스크 문자로 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Column 의 ID 를 설정하여 데이터가 표시되는 형식을 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 컬럼은 inputType=custom + typeGetter(col1=text / col2=textarea / col3=textImage / col4=secret), dataType=number.\n[절차] rowIndex / columnInfo(Column ID) / displayFormat 선택 -> setCellDisplayFormat 실행.\n[확인] columnInfo 를 인덱스 대신 Column ID(col1~col4) 로 지정해도 동일 동작. 리턴창에 변경 전·후 표시값 출력."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (displayFormat 마스크가 가공할 원본 숫자 데이터)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "1000", "col2": "2000", "col3": "3000", "col4": "4000" },
        { "col1": "1500", "col2": "2500", "col3": "3500", "col4": "4500" },
        { "col1": "2000", "col2": "3000", "col3": "4000", "col4": "5000" },
        { "col1": "2500", "col2": "3500", "col3": "4500", "col4": "5500" }
    ]);

    // target 생성
    //  4개 컬럼 모두 inputType=custom + typeGetter 로 Cell 의 inputType 을 각각 다르게 구성 (allow-list 5종 : text/textarea/textImage/secret)
    //  셀 dataType=number 로 두어 displayFormat("#,##0" 등) 마스크가 표시값에 적용되는지 확인
    //   col1 : Cell inputType=text       (메서드 allow-list O)
    //   col2 : Cell inputType=textarea   (메서드 allow-list O)
    //   col3 : Cell inputType=textImage  (메서드 allow-list O)
    //   col4 : Cell inputType=secret     (메서드 allow-list O / 마스킹 표시이나 displayFormat 적용 대상)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:640px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" inputType="text" id="hcol1" value="Cell text (custom)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol2" value="Cell textarea (custom)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol3" value="Cell textImage (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="Cell secret (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" inputType="custom" dataType="number" id="col1" dataList="col1" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="160" inputType="custom" dataType="number" id="col2" dataList="col2" typeGetter="scwin.target1_textareaTypeGetter"></w2:column>';
    strTarget += '<w2:column width="160" inputType="custom" dataType="number" id="col3" dataList="col3" typeGetter="scwin.target1_textImageTypeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" dataType="number" id="col4" dataList="col4" typeGetter="scwin.target1_secretTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// col1(custom) : 각 Cell 을 inputType=text 로 구성 (dataType=number)
scwin.target1_textTypeGetter = function (info) {
    return { id: 'cell_text_' + info.rowIndex + '_' + info.colIndex, inputType: 'text', dataType: 'number', options: {} };
};
// col2(custom) : 각 Cell 을 inputType=textarea 로 구성 (dataType=number)
scwin.target1_textareaTypeGetter = function (info) {
    return { id: 'cell_textarea_' + info.rowIndex + '_' + info.colIndex, inputType: 'textarea', dataType: 'number', options: {} };
};
// col3(custom) : 각 Cell 을 inputType=textImage 로 구성 (dataType=number)
scwin.target1_textImageTypeGetter = function (info) {
    return { id: 'cell_textImage_' + info.rowIndex + '_' + info.colIndex, inputType: 'textImage', dataType: 'number', options: {} };
};
// col4(custom) : 각 Cell 을 inputType=secret 로 구성 (dataType=number)
scwin.target1_secretTypeGetter = function (info) {
    return { id: 'cell_secret_' + info.rowIndex + '_' + info.colIndex, inputType: 'secret', dataType: 'number', options: {} };
};



// 해당 Cell 의 표시값(displayFormat 등 포맷 적용된 화면값)을 조회
//  getCellDisplayData(rowIndex, columnIndex) : displayFormat 등이 적용된 표시값을 반환 (columnIndex 는 인덱스 또는 Column ID)
scwin.getCellDisp = function (rowIndex, columnInfo) {
    try {
        return scwin.target1.getCellDisplayData(rowIndex, columnInfo);
    } catch (e) {
        return "(표시값 조회오류)";
    }
};



// setCellDisplayFormat 실행 : columnInfo 를 Column ID(문자열)로 지정하여 displayFormat 마스크를 적용하고 변경 전/후 표시값을 리턴창에 출력
scwin.btn_setCellDisplayFormat_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // _2 : columnInfo 를 Column ID(문자열)로 그대로 전달 (Number 변환하지 않음)
    let columnInfo = par_columnInfo.getValue();
    let displayFormat = par_displayFormat.getValue();

    // 변경 전 표시값
    let before = scwin.getCellDisp(rowIndex, columnInfo);

    // 메소드 실행 (전제 미충족 시 false 반환)
    let ret = scwin.target1.setCellDisplayFormat(rowIndex, columnInfo, displayFormat);

    // 변경 후 표시값
    let after = scwin.getCellDisp(rowIndex, columnInfo);

    let changed = (before !== after);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellDisplayFormat(" + rowIndex + ", '" + columnInfo + "', '" + displayFormat + "')"
        + " | 변경 전 표시값 : " + before + " -> 변경 후 표시값 : " + after
        + " | 변경됨 : " + changed
        + (ret === false ? " (전제 미충족 -> 미동작)" : ""));
}
